// Package code holds the bee error codes (listed in the file "code", code.go
// is generated by `const code`) and Error, the typed error of a job.
// One table for all job types: audio, video, images.
//
// Whether a job can be retried is a property of the code (Code.Retryable),
// and so is whether the same job can be delivered again (Code.Redeliver):
// an expired url is retried only by a new job with a fresh link.
package code

import (
	"context"
	"errors"
	"fmt"
)

// Error is a failed job. Retryable mirrors Code.Retryable so the client
// needs no code table. Err is the cause and never goes into json: it may
// hold ffmpeg output or a url
type Error struct {
	Code      Code   `json:"code"`
	Message   string `json:"message"`
	Retryable bool   `json:"retryable"`
	Err       error  `json:"-"`
}

// New returns an error with code c; err is the cause, nil if there is none
func New(c Code, message string, err error) *Error {
	return &Error{
		Code:      c,
		Message:   message,
		Retryable: c.Retryable(),
		Err:       err,
	}
}

// Error returns the code, the message and the cause, if any
func (a *Error) Error() string {
	if a.Err != nil {
		return fmt.Sprintf("%s: %s: %v", a.Code, a.Message, a.Err)
	}

	return fmt.Sprintf("%s: %s", a.Code, a.Message)
}

// Unwrap returns the cause
func (a *Error) Unwrap() error {
	return a.Err
}

// As returns any error as *Error: a typed one as is (even wrapped), a
// context end and everything else as INTERNAL_TEMPORARY_ERROR
func As(err error) *Error {
	if err == nil {
		return nil
	}

	// already typed, possibly wrapped
	var e *Error
	if errors.As(err, &e) {
		return e
	}

	// the job context ended or an unexpected failure
	switch {
	case errors.Is(err, context.DeadlineExceeded):
		return New(InternalTemporaryError, "job timed out", err)
	case errors.Is(err, context.Canceled):
		return New(InternalTemporaryError, "job cancelled", err)
	}

	return New(InternalTemporaryError, err.Error(), err)
}
